import Image from "next/image";

/**
 * The official logo files in public/brand, generated by
 * scripts/brand-assets.py (width/height are the files' own pixel sizes).
 *
 * - lockup: mark + "SEQ Elevate" + "Skills for the Future". Needs about
 *   160 px of width for the tagline to stay readable — for the landing page
 *   and the sign-in screens, not the header.
 * - mark: the arcs alone. Only ever used right next to the product name in
 *   text, so it is decorative (empty alt) and the name isn't read out twice.
 */
export const BRAND_ASSETS = {
  lockup: {
    src: "/brand/seq-elevate-lockup.png",
    width: 612,
    height: 314,
    alt: "SEQ Elevate — Skills for the Future",
  },
  mark: {
    src: "/brand/seq-elevate-mark.png",
    width: 199,
    height: 312,
    alt: "",
  },
} as const;

/**
 * The SEQ Elevate logo at a given display width; the height follows the
 * logo's proportions. Logos sit at the top of the page, so they load eagerly
 * instead of waiting for the lazy-load observer.
 */
export function BrandLogo({
  variant,
  width,
  className,
}: {
  variant: keyof typeof BRAND_ASSETS;
  /** Display width in CSS pixels. */
  width: number;
  className?: string;
}) {
  const asset = BRAND_ASSETS[variant];
  return (
    <Image
      src={asset.src}
      alt={asset.alt}
      width={width}
      height={Math.round((width * asset.height) / asset.width)}
      loading="eager"
      className={className}
    />
  );
}
